function equipmentRules(p,a,ids,data){const c=configuration(p,a,ids),seen=new Set(),out=[];for(const n of [...p.wargear,...c.options.map(o=>o.name)])for(const r of gearText(n,data))if(!seen.has(r.name.toLowerCase())){seen.add(r.name.toLowerCase());out.push(r);}return out;}
root.RosterModel={membership,availableOptions,requiredOptions,configuration,addEntry,total,allEntries,warriorCount,capacity,independent,move,removeWarband,migrate,withoutLegacy,prune,gearEffect,effectiveStats,gearText,equipmentRules,missingChoices};
